#include <stdio.h>

void swap(int *left, int *right) {
}

int main(void) {
    int left = 10;
    int right = 20;
    swap(&left, &right);
    printf("%d %d\n", left, right);
    return 0;
}

challenge.solution:
#include <stdio.h>

void swap(int *left, int *right) {
    int temporary = *left;
    *left = *right;
    *right = temporary;
}

int main(void) {
    int left = 10; int right = 20; swap(&left, &right); printf("%d %d\n", left, right); return 0;
}

